  useEffect(()=>{const sourceCurrency=String(currency||'').trim().toUpperCase(),targetCurrency=String(defaultCurrency||'TWD').trim().toUpperCase();if(!amount){setExchangeRate(1);setBaseAmount('');setFxSource('');return}if(sourceCurrency===targetCurrency){setExchangeRate(1);setBaseAmount(amount);setFxSource('同幣別');return}setFxSource('');const timer=window.setTimeout(async()=>{setFxLoading(true);try{const{data,error}=await supabase.functions.invoke('bot-exchange-rate',{body:{from:sourceCurrency,to:targetCurrency,date:previousWorkday(occurred.slice(0,10)),previousWorkday:true}});if(error)throw error;if(data?.error)throw new Error(data.error);const rate=Number(data?.rate);if(!Number.isFinite(rate)||rate<=0)throw new Error('找不到可用匯率');setExchangeRate(rate);setBaseAmount(String(Math.round(Number(amount)*rate)));setFxSource(`臺灣銀行 ${data.rateDate||previousWorkday(occurred.slice(0,10))}（前一工作日・${data?.rateLabel||'現金匯率－本行賣出'}）`)}catch(e:any){setExchangeRate(0);setBaseAmount('');setFxSource('匯率取得失敗');done(`匯率取得失敗：${e.message||e}`)}finally{setFxLoading(false)}},450);return()=>window.clearTimeout(timer)},[amount,currency,defaultCurrency,occurred])
