function Todos({user,items,categories,done,onItemsChange}:any){
  const[title,setTitle]=useState(''),[date,setDate]=useState(today()),[location,setLocation]=useState(''),[category,setCategory]=useState(''),[editing,setEditing]=useState<Todo|null>(null),[showCompleted,setShowCompleted]=useState(false),[saving,setSaving]=useState(false)
  const list=categories.filter((x:Category)=>x.scope==='todo')
  const active=items.filter((x:Todo)=>!x.is_done)
  const completed=items.filter((x:Todo)=>x.is_done)
  function reset(){setTitle('');setDate(today());setLocation('');setCategory('');setEditing(null)}
  async function save(e:FormEvent){
    e.preventDefault();if(saving)return;setSaving(true)
    const payload={title:title.trim(),due_at:new Date(date+'T09:00:00').toISOString(),remind_before_minutes:30,location_name:location.trim(),note:editing?.note||'',is_done:editing?.is_done||false,category_id:category||null}
    try{
      if(editing){await updateLocal(user.id,'todos',editing.id,payload);onItemsChange((current:Todo[])=>current.map(x=>x.id===editing.id?{...x,...payload,_sync:'pending'}:x));done('待辦已更新，將於連線時同步',false)}
      else{const row=await createLocal(user.id,'todos',payload);onItemsChange((current:Todo[])=>[...current,row].sort((a,b)=>new Date(a.due_at).getTime()-new Date(b.due_at).getTime()));done(navigator.onLine?'待辦已新增，正在同步':'待辦已新增至本機，連線後自動同步',false)}
      reset()
    }catch(error:any){done(`待辦儲存失敗：${error?.message||'無法寫入本機資料'}`,false)}finally{setSaving(false)}
  }
  function openEdit(x:Todo){setEditing(x);setTitle(x.title);setDate(x.due_at.slice(0,10));setLocation(x.location_name||'');setCategory(x.category_id||'')}
  async function toggle(x:Todo){
    const is_done=!x.is_done
    onItemsChange((current:Todo[])=>current.map(item=>item.id===x.id?{...item,is_done,_sync:'pending'}:item))
    try{await updateLocal(user.id,'todos',x.id,{is_done});done(is_done?'已移至完成事項，將自動同步':'已恢復至待辦清單，將自動同步',false)}catch(error:any){onItemsChange((current:Todo[])=>current.map(item=>item.id===x.id?{...item,is_done:x.is_done}:item));done(`更新失敗：${error?.message||'無法寫入本機資料'}`,false)}
  }
  const row=(x:Todo)=><div className={'todo-row '+(x.is_done?'done':'')} key={x.id}><button type="button" className="todo-check" title={x.is_done?'恢復待辦':'標示完成'} onClick={()=>toggle(x)}>{x.is_done?<Check size={16}/>:null}</button><button type="button" className="todo-content" onClick={()=>openEdit(x)}><b>{x.title}{x._sync==='pending'&&<small className="todo-pending">・待同步</small>}</b><small>{new Date(x.due_at).toLocaleString('zh-TW')} {x.location_name&&'・'+x.location_name}</small></button></div>
  return <div className="twocol"><form className="panel" onSubmit={save}><h2>{editing?'修改待辦':'新增待辦'}</h2><input placeholder="待辦事項" value={title} onChange={e=>setTitle(e.target.value)} required/><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">未分類</option>{list.map((x:Category)=><option key={x.id} value={x.id}>{x.name}</option>)}</select><input placeholder="地點" value={location} onChange={e=>setLocation(e.target.value)}/><button disabled={saving}>{saving?'儲存中…':editing?'儲存修改':'加入'}</button>{editing&&<button type="button" className="secondary-form-button" onClick={reset}>取消修改</button>}</form><section className="panel"><h2>待辦清單</h2>{active.length?active.map(row):<p className="empty">目前沒有未完成事項</p>}<button type="button" className="completed-toggle" onClick={()=>setShowCompleted(v=>!v)}><span>已完成事項（{completed.length}）</span><ChevronDown className={showCompleted?'open':''} size={18}/></button>{showCompleted&&<div className="completed-list">{completed.length?completed.map(row):<p className="empty">尚無完成事項</p>}</div>}</section></div>}

function MorePage({quickNav,featureOrder,featureDefs,onOpen,user,done}:any){
  const fallback=['home','accounts','ledger','todo','journal','travel','settings']
  const initial=[...(featureOrder?.length?featureOrder:fallback),...fallback].filter((id:string,i:number,a:string[])=>featureDefs[id]&&a.indexOf(id)===i)
  const[order,setOrder]=useState<string[]>(initial),[dragging,setDragging]=useState('')
  useEffect(()=>{const next=[...(featureOrder?.length?featureOrder:fallback),...fallback].filter((id:string,i:number,a:string[])=>featureDefs[id]&&a.indexOf(id)===i);setOrder(next)},[JSON.stringify(featureOrder||[])])
  const items=order.filter(id=>!quickNav.includes(id))
  async function drop(target:string){if(!dragging||dragging===target)return;const next=[...order],from=next.indexOf(dragging),to=next.indexOf(target);if(from<0||to<0)return;next.splice(to,0,next.splice(from,1)[0]);setOrder(next);setDragging('');try{const{error}=await supabase.rpc('update_feature_order',{p_feature_order:next});if(error)throw error;done('功能順序已更新')}catch(error:any){done(`排序儲存失敗：${error?.message||'無法連線到資料庫'}`,false)}}
  return <section className="panel more-page"><div className="more-head"><div><h2>更多功能</h2><small>長按或拖曳入口即可調整順序</small></div></div><div className="feature-grid">{items.map(id=>{const def=featureDefs[id];if(!def)return null;const[Icon,label]=def;return <button type="button" draggable onDragStart={()=>setDragging(id)} onDragOver={e=>e.preventDefault()} onDrop={()=>drop(id)} onClick={()=>onOpen(id)} key={id}><span><Icon size={28}/></span><b>{label}</b></button>})}</div></section>
}

function JournalPage({user,items,categories,done}:any){
  const moodList=categories.filter((x:Category)=>x.scope==='mood');const currentMonth=today().slice(0,7);const availableMonths=Array.from(new Set([currentMonth,...items.map((x:Journal)=>x.entry_date.slice(0,7))])).sort().reverse();const[selectedMonth,setSelectedMonth]=useState(currentMonth),[editingId,setEditingId]=useState<string|null>(null),[mood,setMood]=useState('😊'),[moodCategory,setMoodCategory]=useState(''),[body,setBody]=useState(''),[date,setDate]=useState(today()),[file,setFile]=useState<File>(),[existingCover,setExistingCover]=useState<string|null>(null)
  const monthItems=items.filter((x:Journal)=>x.entry_date.slice(0,7)===selectedMonth).sort((a:Journal,b:Journal)=>a.entry_date.localeCompare(b.entry_date))
  function reset(){setEditingId(null);setMood('😊');setMoodCategory('');setBody('');setDate(today());setFile(undefined);setExistingCover(null)}
  function editEntry(x:Journal){setEditingId(x.id);setDate(x.entry_date);setMood(x.mood);setMoodCategory(x.mood_category_id||'');setBody(x.body||'');setExistingCover((x as any).cover_path||null);setFile(undefined);window.scrollTo({top:0,behavior:'smooth'})}
  async function save(e:FormEvent){e.preventDefault();let path:string|undefined=existingCover||undefined;if(file){path=`${user.id}/${date}/${crypto.randomUUID()}-${file.name}`;const u=await supabase.storage.from('journal-images').upload(path,file);if(u.error)return alert(u.error.message)}try{const{error}=await supabase.rpc('save_journal_entry',{p_entry_id:editingId,p_entry_date:date,p_mood:mood,p_body:body,p_mood_category_id:moodCategory||null,p_cover_path:path||null});if(error)throw error;reset();setSelectedMonth(date.slice(0,7));done(editingId?'日記已更新':'日記已儲存')}catch(error:any){done(`日記儲存失敗：${error?.message||'無法連線到資料庫'}`,false)}}
  async function remove(){if(!editingId||!confirm('確定刪除這篇日記？'))return;try{const{error}=await supabase.rpc('delete_journal_entry',{p_entry_id:editingId});if(error)throw error;reset();done('日記已刪除')}catch(error:any){done(`日記刪除失敗：${error?.message||'無法連線到資料庫'}`,false)}}
  return <><form className="panel journal" onSubmit={save}><h2>{editingId?'修改日記':'寫下今天'}</h2><input type="date" value={date} onChange={e=>setDate(e.target.value)}/>{moodList.length?<div className="mood-category-grid">{moodList.map((x:Category)=><button type="button" key={x.id} className={moodCategory===x.id?'on':''} onClick={()=>{setMoodCategory(x.id);setMood(x.icon||x.name)}}>{x.icon||'●'}<small>{x.name}</small></button>)}</div>:<div className="moods">{['😍','😊','😐','😮‍💨','😢'].map(x=><button key={x} type="button" className={mood===x?'on':''} onClick={()=>setMood(x)}>{x}</button>)}</div>}<textarea placeholder="今天發生了什麼？" value={body} onChange={e=>setBody(e.target.value)}/><input type="file" accept="image/*" onChange={e=>setFile(e.target.files?.[0])}/><button>{editingId?'儲存修改':'儲存日記'}</button>{editingId&&<div className="journal-edit-actions"><button type="button" className="secondary-form-button" onClick={reset}>取消修改</button><button type="button" className="delete-full" onClick={remove}>刪除這篇日記</button></div>}</form><section className="panel"><div className="monthly-dump-head"><h2>Monthly Dump</h2><input type="month" value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)}/></div><div className="dump">{monthItems.length?monthItems.map((x:Journal)=><button type="button" className="dump-entry" key={x.id} onClick={()=>editEntry(x)}><b>{new Date(x.entry_date+'T00:00:00').getDate()}</b><span>{x.mood}</span><small>{x.body.slice(0,28)}</small></button>):<p className="empty monthly-empty">{selectedMonth} 尚無日記</p>}</div>{availableMonths.length>1&&<div className="month-shortcuts">{availableMonths.map(month=><button type="button" className={selectedMonth===month?'on':''} onClick={()=>setSelectedMonth(month)} key={month}>{month}</button>)}</div>}</section></>}

function SettingsPage({user,settings,categories,accounts,txs,done}:any){const[tab,setTab]=useState<'account'|'ledger'|'todo'|'journal'>('account'),[nickname,setNickname]=useState(settings.nickname||''),[currency,setCurrency]=useState(settings.default_currency||'TWD'),[quickNav,setQuickNav]=useState<string[]>(settings.quick_nav?.length?settings.quick_nav:['home','accounts','ledger','todo']),[from,setFrom]=useState(''),[to,setTo]=useState(''),[importing,setImporting]=useState(false),[dragCategory,setDragCategory]=useState(''),[categoryKind,setCategoryKind]=useState<'expense'|'income'>('expense'),[categoryIconEditor,setCategoryIconEditor]=useState<any>(null),[categoryEditorName,setCategoryEditorName]=useState(''),[categoryEditorIcon,setCategoryEditorIcon]=useState('🏷️');useEffect(()=>{setNickname(settings.nickname||'');setCurrency(settings.default_currency||'TWD');setQuickNav(settings.quick_nav?.length?settings.quick_nav:['home','accounts','ledger','todo'])},[settings]);function toggleQuickNav(id:string){setQuickNav(current=>current.includes(id)?current.length===1?(done('自選頁面至少要保留一個',false),current):current.filter(x=>x!==id):current.length>=4?(done('自選頁面最多只能選四個',false),current):[...current,id])}async function save(e:FormEvent){e.preventDefault();const featureOrder=settings.feature_order?.length?settings.feature_order:['home','accounts','ledger','todo','journal','travel','settings'];const{error}=await supabase.from('user_settings').upsert({user_id:user.id,nickname,default_currency:currency,quick_nav:quickNav,feature_order:featureOrder,updated_at:new Date().toISOString()});done(error?error.message:'設定已儲存')}
async function add(scope:Category['scope'],parent_id:string|null=null){const txKind=scope==='transaction'?categoryKind:null;const actualParent=scope==='transaction'&&categoryKind==='income'?null:parent_id;if(scope==='transaction'&&actualParent){setCategoryEditorName('');setCategoryEditorIcon('🏷️');setCategoryIconEditor({scope,parent_id:actualParent,transaction_kind:txKind});return}const name=prompt(actualParent?'子分類名稱':categoryKind==='income'?'收入分類名稱':'母分類名稱');if(!name?.trim())return;const icon=scope==='mood'?prompt('心情圖示，例如 😊','😊'):null,list=categories.filter((x:Category)=>x.scope===scope&&(x.parent_id||null)===(actualParent||null)&&x.transaction_kind===txKind);const{error}=await supabase.from('user_categories').insert({user_id:user.id,scope,name:name.trim(),icon,parent_id:actualParent,transaction_kind:txKind,sort_order:(list.length+1)*100});done(error?error.message:'分類已新增')}
async function saveCategoryIcon(e:FormEvent){e.preventDefault();if(!categoryIconEditor||!categoryEditorName.trim())return;const values={name:categoryEditorName.trim(),icon:categoryEditorIcon};if(categoryIconEditor.id){const{error}=await supabase.from('user_categories').update(values).eq('id',categoryIconEditor.id);if(error)return done(error.message,false)}else{const list=categories.filter((x:Category)=>x.scope==='transaction'&&x.parent_id===categoryIconEditor.parent_id);const{error}=await supabase.from('user_categories').insert({user_id:user.id,scope:'transaction',name:values.name,icon:values.icon,parent_id:categoryIconEditor.parent_id,transaction_kind:categoryIconEditor.transaction_kind,sort_order:(list.length+1)*100});if(error)return done(error.message,false)}setCategoryIconEditor(null);done('子分類已儲存')}
async function edit(x:Category){if(x.scope==='transaction'&&x.parent_id){setCategoryEditorName(x.name);setCategoryEditorIcon(x.icon||'🏷️');setCategoryIconEditor(x);return}const name=prompt('修改分類名稱',x.name);if(!name?.trim())return;const icon=x.scope==='mood'?prompt('修改心情圖示',x.icon||'😊'):x.icon;await supabase.from('user_categories').update({name:name.trim(),icon}).eq('id',x.id);done()}async function remove(x:Category){if(!confirm(`確定刪除「${x.name}」？既有資料會保留並改為未分類。`))return;await supabase.from('user_categories').delete().eq('id',x.id);done()}async function dropCategory(target:Category){if(!dragCategory||dragCategory===target.id)return;const source=categories.find((x:Category)=>x.id===dragCategory);if(!source||source.scope!==target.scope||source.transaction_kind!==target.transaction_kind||(source.parent_id||null)!==(target.parent_id||null)){setDragCategory('');return}const siblings=categories.filter((x:Category)=>x.scope===source.scope&&x.transaction_kind===source.transaction_kind&&(x.parent_id||null)===(source.parent_id||null)).sort((a:Category,b:Category)=>a.sort_order-b.sort_order),from=siblings.findIndex((x:Category)=>x.id===source.id),to=siblings.findIndex((x:Category)=>x.id===target.id);if(from<0||to<0)return;const reordered=[...siblings];reordered.splice(to,0,reordered.splice(from,1)[0]);setDragCategory('');try{const items=reordered.map((x:Category,i:number)=>({id:x.id,sort_order:(i+1)*100}));const{error}=await supabase.rpc('reorder_user_categories',{items});if(error)throw error;done('分類順序已更新')}catch(error:any){done(`排序失敗：${error?.message||'無法連線到資料庫'}`)}}

const manager=(scope:Category['scope'],title:string)=>{const base=categories.filter((x:Category)=>x.scope===scope),list=scope==='transaction'?base.filter((x:Category)=>x.transaction_kind===categoryKind):base,parents=scope==='transaction'&&categoryKind==='expense'?list.filter((x:Category)=>!x.parent_id).sort((a:Category,b:Category)=>a.sort_order-b.sort_order):list.filter((x:Category)=>!x.parent_id).sort((a:Category,b:Category)=>a.sort_order-b.sort_order);return <section className="panel"><div className="section-head category-heading"><div className="category-heading-row"><h2>{title}</h2><button type="button" className="category-add-circle" title={scope==='transaction'?'新增母分類':'新增分類'} aria-label={scope==='transaction'?'新增母分類':'新增分類'} onClick={()=>add(scope)}><Plus size={18}/></button>{scope==='transaction'&&<div className="category-kind-switch"><button className={categoryKind==='expense'?'on':''} onClick={()=>setCategoryKind('expense')}>支出</button><button className={categoryKind==='income'?'on':''} onClick={()=>setCategoryKind('income')}>收入</button></div>}</div></div>{parents.length?parents.map((x:Category)=><div className="category-block" key={x.id}><div className={scope==='transaction'&&categoryKind==='income'?"subcategory-drag-row income-category-row":"category-drag-row"} draggable onDragStart={()=>setDragCategory(x.id)} onDragEnd={()=>setDragCategory('')} onDragOver={e=>e.preventDefault()} onDrop={()=>dropCategory(x)}><GripVertical className="drag-handle"/><span className={categoryKind==='income'?"child-category-name":"parent-category-name"}>{x.icon&&`${x.icon} `}{x.name}</span><div className="row-actions">{scope==='transaction'&&categoryKind==='expense'&&<button onClick={()=>add(scope,x.id)}><Plus/></button>}<button onClick={()=>edit(x)}><Pencil/></button><button className="danger" onClick={()=>remove(x)}><Trash2/></button></div></div>{scope==='transaction'&&categoryKind==='expense'&&<div className="subcategories">{list.filter((c:Category)=>c.parent_id===x.id).sort((a:Category,b:Category)=>a.sort_order-b.sort_order).map((c:Category)=><div className="subcategory-drag-row" draggable onDragStart={()=>setDragCategory(c.id)} onDragEnd={()=>setDragCategory('')} onDragOver={e=>e.preventDefault()} onDrop={()=>dropCategory(c)} key={c.id}><GripVertical className="drag-handle"/><span className="child-category-name"><i>{c.icon||'🏷️'}</i>{c.name}</span><span><button onClick={()=>edit(c)}><Pencil/></button><button className="danger" onClick={()=>remove(c)}><Trash2/></button></span></div>)}</div>}</div>):<p className="empty">尚未建立{scope==='todo'?'待辦分類':scope==='mood'?'心情分類':categoryKind==='expense'?'支出分類':'收入分類'}</p>}</section>}
function iso(v:any){const noon=(y:number,m:number,d:number)=>new Date(y,m-1,d,12,0,0).toISOString();if(v instanceof Date)return noon(v.getFullYear(),v.getMonth()+1,v.getDate());if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return noon(d.y,d.m,d.d)}const text=String(v??'').trim();const matched=text.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);if(matched)return noon(Number(matched[1]),Number(matched[2]),Number(matched[3]));const d=new Date(text);return isNaN(d.getTime())?'':noon(d.getFullYear(),d.getMonth()+1,d.getDate())}
function exportExcel(){
 const rows=txs.filter((x:Tx)=>{const d=x.occurred_at.slice(0,10);return(!from||d>=from)&&(!to||d<=to)}).map((x:Tx)=>{
  const cat=categories.find((c:Category)=>c.id===x.category_id),parent=cat?.parent_id?categories.find((c:Category)=>c.id===cat.parent_id):undefined
  const parentName=x.kind==='expense'?(parent?.name||(!cat?.parent_id?cat?.name||'':'')):x.kind==='income'?(cat?.name||''):''
  const childName=x.kind==='expense'&&parent?(cat?.name||''):''
  return {'日期':x.occurred_at.slice(0,10),'類型':({expense:'支出',income:'收入',transfer:'轉帳'}as any)[x.kind],'金額':Number(x.amount),'幣值':x.currency,'帳戶':accounts.find((a:Account)=>a.id===x.account_id)?.name||'','母分類':parentName,'子分類':childName,'備註':x.note||''}
 });
 const headers=['日期','類型','金額','幣值','帳戶','母分類','子分類','備註'],ws=XLSX.utils.json_to_sheet(rows,{header:headers});ws['!cols']=[{wch:14},{wch:10},{wch:14},{wch:10},{wch:18},{wch:18},{wch:18},{wch:32}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'記帳紀錄');XLSX.writeFile(wb,`財日記記帳紀錄_${from||'全部'}_${to||'全部'}.xlsx`)
}
async function importExcel(file?:File){
 if(!file)return;setImporting(true)
 try{
  const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),rows=XLSX.utils.sheet_to_json<any>(wb.Sheets[wb.SheetNames[0]],{defval:''}),map:any={支出:'expense',收入:'income',轉帳:'transfer',expense:'expense',income:'income',transfer:'transfer'},inserts:any[]=[],skipped:number[]=[],categoryMisses:string[]=[]
  rows.forEach((r:any,i:number)=>{
   const account=accounts.find((a:Account)=>a.name.trim()===String(r['帳戶']).trim()),kind=map[String(r['類型']).trim()],occurred_at=iso(r['日期']),amount=Number(r['金額']);if(!account||!kind||!occurred_at||!isFinite(amount)){skipped.push(i+2);return}
   const parentName=String(r['母分類']||'').trim(),childName=String(r['子分類']||'').trim(),legacyName=String(r['分類']||'').trim();let category:Category|undefined
   if(kind==='expense'){
    const parent=parentName?categories.find((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='expense'&&!c.parent_id&&c.name.trim()===parentName):undefined
    if(parentName&&!parent)categoryMisses.push(`第 ${i+2} 列：找不到母分類「${parentName}」`)
    if(childName){category=categories.find((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='expense'&&c.parent_id&&(parent?c.parent_id===parent.id:true)&&c.name.trim()===childName);if(!category)categoryMisses.push(`第 ${i+2} 列：找不到子分類「${childName}」${parent?`（${parent.name}）`:''}`)}
    else category=parent||undefined
    if(!category&&legacyName)category=categories.find((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='expense'&&c.name.trim()===legacyName)
   }else if(kind==='income'){
    const incomeName=parentName||childName||legacyName;category=categories.find((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='income'&&c.name.trim()===incomeName);if(incomeName&&!category)categoryMisses.push(`第 ${i+2} 列：找不到收入分類「${incomeName}」`)
   }
   inserts.push({user_id:user.id,kind,amount,currency:String(r['幣值']||account.currency||currency),account_id:account.id,category_id:category?.id||null,note:String(r['備註']||''),occurred_at,is_reimbursable:false,is_advance:false})
  })
  if(!inserts.length)return alert('沒有可匯入的有效資料');const{error}=await supabase.from('transactions').insert(inserts);if(error)throw error;done(`已匯入 ${inserts.length} 筆紀錄${skipped.length?`，略過 ${skipped.length} 筆`:''}${categoryMisses.length?`；${categoryMisses.length} 筆分類未配對`:''}`);if(categoryMisses.length)alert(`以下分類沒有在目前設定中找到，因此匯入為未分類：\n\n${categoryMisses.slice(0,20).join('\n')}${categoryMisses.length>20?'\n…':''}`)
 }catch(e:any){alert(`匯入失敗：${e.message||e}`)}finally{setImporting(false)}
}
const categoryIconModal=categoryIconEditor&&<div className="modal"><form className="panel category-icon-modal" onSubmit={saveCategoryIcon}><button type="button" className="modal-close" onClick={()=>setCategoryIconEditor(null)}><X/></button><h2>{categoryIconEditor.id?'編輯子分類':'新增子分類'}</h2><label>分類名稱<input value={categoryEditorName} onChange={e=>setCategoryEditorName(e.target.value)} required/></label><label>選擇圖示</label><div className="category-icon-library">{CATEGORY_ICON_OPTIONS.map(icon=><button type="button" className={categoryEditorIcon===icon?'on':''} onClick={()=>setCategoryEditorIcon(icon)} key={icon}>{icon}</button>)}</div><button>儲存</button></form></div>;
return <>{categoryIconModal}<div className="settings-tabs">{[['account','帳戶'],['ledger','記帳'],['todo','待辦'],['journal','日記'],['travel','旅遊']].map(([id,label])=><button key={id} className={tab===id?'on':''} onClick={()=>setTab(id as any)}>{label}</button>)}</div>{tab==='account'&&<form className="panel settings-form" onSubmit={save}><h2>帳戶設定</h2><label>暱稱<input value={nickname} onChange={e=>setNickname(e.target.value)}/></label><div className="quick-nav-settings"><div><b>下方自選頁面</b><small>最少選 1 個、最多選 4 個；未選功能會顯示在「更多」。</small></div><div className="quick-nav-options">{[['home','總覽'],['accounts','帳戶'],['ledger','記帳'],['todo','待辦'],['journal','日記'],['travel','旅遊']].map(([id,label])=><label className={quickNav.includes(id)?'selected':''} key={id}><input type="checkbox" checked={quickNav.includes(id)} onChange={()=>toggleQuickNav(id)}/><span>{label}</span></label>)}</div><small>已選 {quickNav.length}／4</small></div><button>儲存</button></form>}{tab==='ledger'&&<>{manager('transaction','記帳分類')}<form className="panel settings-form" onSubmit={save}><label>預設幣值<select value={currency} onChange={e=>setCurrency(e.target.value)}>{['TWD','USD','JPY','KRW','EUR'].map(x=><option key={x}>{x}</option>)}</select></label><button>儲存</button></form><section className="panel excel-tools"><h2>Excel 匯入／匯出</h2><p className="tool-note">欄位：日期、類型、金額、幣值、帳戶、母分類、子分類、備註。支出會先配對母分類，再從該母分類下配對子分類；收入分類填在母分類。帳戶與分類名稱需與系統完全相同。</p><div className="date-range"><label>開始日期<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>結束日期<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><div className="excel-actions"><label className="file-button">{importing?'匯入中…':'匯入 Excel'}<input type="file" accept=".xlsx,.xls" disabled={importing} onChange={e=>{importExcel(e.target.files?.[0]);e.currentTarget.value=''}}/></label><button type="button" onClick={exportExcel}>匯出 Excel</button></div><small>日期留空時匯出全部期間；日期篩選只影響匯出。</small></section></>}{tab==='todo'&&manager('todo','事項分類')}{tab==='journal'&&manager('mood','心情分類')}</>}

